def _word_numbers(quote):
    """Numbers written in words, including compounds ("four hundred and sixty-seven", "sixty-four")."""
    out, cur, run = [], 0, False
    for w in re.findall(r"[a-z]+", str(quote).lower().replace("-", " ")):
        if w in WORDS and not (w == "no" or w == "none"):
            cur += WORDS[w]; run = True
        elif w in SCALE and run:
            cur *= SCALE[w]
        elif w == "and" and run:
            continue
        else:
            if run:
                out.append(cur)
            cur, run = 0, False
    if run:
        out.append(cur)
    return out


def _number_in_quote(value, quote, metric, note=""):
    """The value appears in the quote as digits (commas ignored) or a number word; or it is one named death, one
    item named with "a/an", an explicit none ("no", "not one"), or the stated sum of items the quote lists."""
    q = str(quote).replace(",", "")
    nums = [float(m.group()) for m in re.finditer(r"\d+(?:\.\d+)?", q)]
    if any(abs(n - value) < 1e-9 for n in nums):
        return True
    if any(WORDS.get(w) == value for w in re.findall(r"[a-z]+", str(quote).lower())) or value in _word_numbers(quote):
        return True
    if value == 0 and re.search(r"\b(not one|not a single|no)\b", q, re.I):
        return True
    if value == 1 and re.search(r"\ban?\s+(\w+\s+){0,2}(home|house|cottage|dwelling|residence|business)\b", q, re.I):
        return True
    if "items listed in the quote" in str(note) and nums and abs(sum(nums) - value) < 1e-9:
        return True
    return metric == "deaths" and value == 1 and bool(DEATH_WORDS.search(str(quote)))


def facts():
    f = pd.DataFrame(FACTS, columns=FIELDS)
    f["accessed_utc"] = ACCESSED_UTC
    f["value"] = f.value.astype(float)
    f["hedged"] = f.hedged.astype(bool)
    assert f.metric.isin(METRICS).all(), f"unknown metric: {set(f.metric) - set(METRICS)}"
    assert f.scope.isin(SCOPES).all(), f"unknown scope: {set(f.scope) - set(SCOPES)}"
    bad = [i for i, (v, q, m, n) in enumerate(zip(f.value, f.quote, f.metric, f.note))
           if not _number_in_quote(v, q, m, n)]
    assert not bad, f"number not in quote:\n{f.loc[bad, ['agrn', 'region_name', 'metric', 'value', 'quote']]}"
    long = f[f.quote.str.split().str.len() > 25]
    assert long.empty, f"quote longer than 25 words:\n{long[['agrn', 'region_name', 'quote']]}"
    unit = pd.read_csv(OUT / "key_event_council.csv", dtype={"agrn": str, "region_id": str},
                       usecols=["agrn", "region_id", "region_name"])
    k = f.merge(unit, on=["agrn", "region_id"], how="left", suffixes=("", "_unit"), indicator=True)
    miss = k[k._merge != "both"]
    assert miss.empty, f"not a key-event × council row:\n{miss[['agrn', 'region_id', 'region_name']]}"
    f["region_name"] = k.region_name_unit.values  # the unit's own spelling
    f["_s"] = f.scope.map({s: i for i, s in enumerate(SCOPES)})
    f["_t"] = f.source_type.map({"official": 0, "other": 1, "news": 2}).fillna(3)
    f["_d"] = pd.to_datetime(f.as_of_date.astype(str).str[:10], errors="coerce", format="mixed")
    # interim / superseded counts and single-species livestock rows are never the preferred figure
    f["_m"] = f.note.fillna("").str.contains(MINOR)
    f = f.sort_values(["agrn", "region_id", "metric", "_s", "_m", "_t", "_d", "hedged"],
                      ascending=[True, True, True, True, True, True, False, True], na_position="last")
    f["preferred"] = ~f.duplicated(["agrn", "region_id", "metric"])
    return f[COLS].reset_index(drop=True)


def run():
    f = facts()
    d = DATA / "enrich"
    d.mkdir(parents=True, exist_ok=True)
    f.to_parquet(d / "dl_council.parquet", index=False)
    f.to_csv(d / "dl_council.csv", index=False)
    for (t, u), g in f.groupby(["source_title", "url"], sort=False):
        record_source(f"DL council: {t}", u, None, "public report" if (g.source_type == "official").all()
                      else "public report / news", "dl_council: " + ", ".join(sorted(g.metric.unique())))
    return f


def coverage(f):
    """Rows of the 218 with a preferred value, per metric (and how many are council totals)."""
    p = f[f.preferred]
    out = []
    for m in METRICS:
        x = p[p.metric == m]
        out.append(dict(metric=m, rows=len(x), council_total=int((x.scope == "council_total").sum()),
                        statewide_zero=int((x.scope == "statewide_zero").sum()),
                        fire_in_council=int((x.scope == "fire_in_council").sum()), zeros=int((x.value == 0).sum())))
    return pd.DataFrame(out)


if __name__ == "__main__":
    f = run()
    print(len(f), "facts;", f.url.nunique(), "source documents;",
          f[["agrn", "region_id"]].drop_duplicates().shape[0], "of 218 rows have at least one fact")
    print(coverage(f).to_string(index=False))
    unit = pd.read_csv(OUT / "key_event_council.csv", dtype={"agrn": str, "region_id": str})
    for m, col in [("homes_destroyed", "DL_homes_destroyed_in_council"), ("homes_damaged", "reported_homes_damaged")]:
        had = unit[unit[col].notna()][["agrn", "region_id"]] if col in unit else unit.iloc[:0][["agrn", "region_id"]]
        x = f[f.preferred & (f.metric == m)][["agrn", "region_id"]]
        new = x.merge(had, how="left", indicator=True).query("_merge == 'left_only'")
        print(f"{m}: {len(x)} of 218 rows ({(x.merge(f[f.preferred & (f.metric == m) & (f.scope == 'council_total')][['agrn', 'region_id']]).shape[0])} council totals); "
              f"{len(new)} were blank in key_event_council.{col}")
